# Generated by build.py from recipe.yml for recipe smtp-check-an-app-sent-the-right-mail. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-delivered-to', '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'carol@example.com:carolpass', '--mailbox', 'dave@example.com:davepass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T reset.eml smtp://127.0.0.1:8080/app.example.com --next -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt carol@example.com -T local-link.eml smtp://127.0.0.1:8080/app.example.com --next -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt bob@example.com -T wrong-to.eml smtp://127.0.0.1:8080/app.example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u carol@example.com:carolpass -X "FETCH 1 FLAGS" imap://127.0.0.1:8081/INBOX --next -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u bob@example.com:bobpass -X "FETCH 1 FLAGS" imap://127.0.0.1:8081/INBOX
try { curl.exe -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(DELIVERED-TO%20SUBJECT)" } finally { Stop-Process $server0 }
